import type { MouseEventHandler } from "react";

export function DownloadIconButton({ onDownload }: { onDownload: MouseEventHandler<HTMLButtonElement> }) {
  return (
    <button type="button" aria-label="Download file" onClick={onDownload}>
      <svg aria-hidden="true" viewBox="0 0 16 16"><path d="M8 2v8m-3-3 3 3 3-3M3 13h10" /></svg>
    </button>
  );
}

import { fireEvent, render } from "@testing-library/react";
import { expect, it, vi } from "vitest";
import { DownloadIconButton } from "../src/components/DownloadIconButton";

it("invokes the download handler", () => {
  const onDownload = vi.fn();
  const view = render(<DownloadIconButton onDownload={onDownload} />);
  fireEvent.click(view.container.querySelector("button")!);
  expect(onDownload).toHaveBeenCalledOnce();
});

